EDITORIAL = {}
for line in ROWS.splitlines():
    term, pos, meaning, example, translation = line.split("|")
    assert term not in EDITORIAL
    EDITORIAL[term] = {"pos": pos.split(","), "meaning_vi": meaning,
                       "examples": [{"en": example, "vi": translation, "source": "dhv"}]}

